    stagesDesc: 'مراحل براہ راست آڈیو رومز ہوتے ہیں، جو ٹویٹر اسپیسز کے مقابلے میں ہوتے ہیں، جو براہ راست DeHub میں بنائے جاتے ہیں ۔ ایک میزبان ایک کمرہ کھولتا ہے، مقررین کو اسٹیج پر لاتا ہے، اور سامعین کی کوئی بھی تعداد اسٹیجز کے صفحے یا مشترکہ دعوت نامے کے لنک سے فوری طور پر اندر آسکتی ہے ۔ اسٹیجز کو پیمانے پر حقیقی گفتگو کے لیے ڈیزائن کیا گیا ہے: میزبان کنٹرول کرتے ہیں کہ کون بول سکتا ہے، سامعین براہ راست رد عمل بھیجتے ہیں، اور پورا کمرہ دوبارہ چلانے کے لیے ریکارڈ کیا جا سکتا ہے ۔',
    stagesDesc2: 'جو چیز DeHub اسٹیجز کو الگ کرتی ہے وہ پروڈکشن لیئر ہے ۔ میزبانوں کو ایک DJ طرز کا ساؤنڈ بورڈ ملتا ہے جو صوتی اثرات، ان کے اپنے میوزک کلپس اور براہ راست ریڈیو اسٹیشنوں کو شائع شدہ کمرے کے آڈیو، نیز صوتی اثرات میں ملا دیتا ہے، تاکہ ایک اسٹیج کانفرنس کال کے بجائے ایک تیار کردہ شو کی طرح محسوس کر سکے ۔ میزبان اپنی اسکرین شیئر کر سکتے ہیں، بغیر کسی OBS یا اسٹریم کیز والے براؤزر سے پوری چیز چلا سکتے ہیں، اور کمرے کو پہلے سے شیڈول کر سکتے ہیں تاکہ ناظرین دروازے کھلنے سے پہلے انتظار کر سکیں ۔',
    stagesDesc3: 'کمرہ پڑھنے کے قابل بھی ہے ۔ لائیو سب ٹائٹلز کیپشن ہر اسپیکر بات کرتے وقت اور ہر سننے والا جس زبان میں پڑھ رہا ہے اس میں اس کا ترجمہ کیا جاتا ہے، لہذا اسٹیج کو اس زبان میں فالو کیا جا سکتا ہے جس میں اسٹیج پر کوئی نہیں بولتا ۔ لائیو ڈبنگ ایک قدم اور آگے جاتی ہے اور میزبان کی اپنی کلون کردہ آواز میں کمرے کو بلند آواز سے بولتی ہے، جسے ڈی ہب ٹوکن میں منٹ کے حساب سے بل کیا جاتا ہے ۔ ایک لائیو ٹرانسکرپٹ دراز اور ٹیکسٹ ٹو اسپیچ کمرے کو مائیکروفون کے بغیر قابل استعمال رکھتا ہے، اور ایک مستقل کونے والا منی پلیئر آپ کو اسٹیج کے ڈرامے کے دوران باقی ایپ کو براؤز کرتے رہنے دیتا ہے ۔',
    stagesB1: 'میزبان اور بولیں:',
    stagesB1Desc: 'اسٹیج شروع کریں، مقررین کو اسٹیج پر مدعو کریں، شرکاء کو خاموش کریں یا ہٹائیں، اور میزبان کنٹرولز سے ریئل ٹائم میں کمرے کا انتظام کریں ۔',
    stagesB2: 'رد عمل اور صوتی تختہ:',
    stagesB2Desc: 'سامعین براہ راست ایموجی ری ایکشنز بھیجتے ہیں، اور میزبان کلک فری کیوئنگ اور صوتی اثرات کو براہ راست کمرے کے آڈیو میں ملا کر DJ طرز کا ساؤنڈ بورڈ چلاتے ہیں ۔',
    stagesB3: 'ٹرانسکرپٹس اور ٹی ٹی ایس:',
    stagesB3Desc: 'ایک لائیو ٹرانسکرپٹ دراز کمرے کی کیپشن دیتا ہے جیسا کہ یہ ہوتا ہے، اور ٹیکسٹ ٹو سپیچ آپ کو مائیکروفون کے بغیر حصہ لینے دیتا ہے ۔',
    stagesB4: 'ریکارڈنگز:',
    stagesB4Desc: 'مراحل ریکارڈ کرتے ہیں، اور ریکارڈنگ اس کارڈ سے واپس چلتی ہے جس پر وہ ظاہر ہوتا ہے — قابل طلب، جس رفتار سے آپ منتخب کرتے ہیں، شیئر شیٹ سے براہ راست شرعی اور قابل واپسی ۔ ایک مشترکہ کارنر پلیئر اسے ویب اور موبائل پر لے جاتا ہے ۔',
    stagesB5: 'شیڈول کریں اور یاد دلائیں:',
