    stagesB6: 'ذیلی عنوانات اور ترجمہ:',
    stagesB6Desc: 'ہر اسپیکر کے لائیو کیپشنز، جس زبان میں ہر سننے والا پڑھ رہا ہے اس میں ترجمہ کیا جاتا ہے ۔ کمرے کے ختم ہونے کے بعد پائیدار ٹرانسکرپٹ کو الگ رکھا جاتا ہے ۔',
    stagesB7: 'لائیو ڈبنگ:',
    stagesB7Desc: 'میزبان کی اپنی کلون کردہ آواز میں کمرے کو کسی دوسری زبان میں ڈب کریں، جس کی ادائیگی بٹوے سے DeHub ٹوکن میں منٹ کے حساب سے کی جاتی ہے ۔',
    stagesB8: 'سامعین کی چیٹ اور اسکرین شیئر:',
