    tvRadioTitle: 'ٹی وی، موسیقی اور ریڈیو',
    tvRadioDesc: 'تخلیق کار کے اپ لوڈز کے علاوہ، DeHub ہمیشہ تفریحی سطحوں پر جہاز بھیجتا ہے لہذا جب آپ ایپ کھولتے ہیں تو دیکھنے یا سننے کے لیے کچھ ہوتا ہے ۔ یہ دبلے پتلے تجربات مسلسل چلتے ہیں اور تیرتے ہوئے پلیئرز کے ذریعے پروڈکٹ کے ارد گرد آپ کی پیروی کرتے ہیں، لہذا جب آپ کہیں اور تشریف لاتے ہیں تو میڈیا کبھی نہیں رکتا ہے ۔',
    tvRadioB1: 'ڈی ہب ٹی وی:',
