    walletHubDesc2: 'تخلیق کاروں اور پاور صارفین کے لیے، والٹ ایک مکمل فنانس سطح میں پھیل جاتا ہے ۔ کمانڈ سینٹر وقت کے ساتھ آمدنی کا تصور کرتا ہے، ہر ٹرانزیکشن کو توڑتا ہے، اور کراس چین ڈپازٹس کو ہینڈل کرتا ہے، جبکہ سرشار صفحات آپ کو DeHub چھوڑنے کے بغیر DeHub ٹوکن خریدنے، داؤ پر لگانے اور پلنے دیتے ہیں ۔',
    walletHubB1: 'والٹ:',
