    walletHubB3: 'ٹوکن خریدیں:',
    walletHubB3Desc: 'بلٹ ان خرید فلو کے ذریعے کارڈ یا کرپٹو کے ساتھ براہ راست ایپ میں اپنا بیلنس ٹاپ اپ کریں ۔',
