    workDesc2: 'کیونکہ یہ آبائی ہے، باؤنٹی ہنٹنگ پورے ماحولیاتی نظام کے لئے ترقی کے انجن کے طور پر دگنی ہو جاتی ہے ۔ تخلیق کار اس کا استعمال مشغولیت کو آگے بڑھانے اور اپنے کام کو پھیلانے والے حصص، کلپس، رد عمل یا مواد کے لئے انعامات پوسٹ کرکے اپنی کمیونٹیز کی تعمیر کے لئے کرتے ہیں ۔ پروجیکٹس اور وسیع تر ڈی ہب کمیونٹی اس کا استعمال ماحولیاتی نظام کو خود کو فروغ دینے اور بڑھانے کے لئے کرتی ہے، جس سے شکاریوں کو ان کاموں کے لئے انعام ملتا ہے جو نئے لوگوں کو لاتے ہیں ۔ وہی نظام جو معاہدے کو طے کرتا ہے وہ کمیونٹی کی مصروفیت کے کام کو بھی طے کرتا ہے ۔',
    workB1: 'ایک انعام پوسٹ کریں:',
