    workB2: 'شکاری بنیں:',
    workB2Desc: 'کھلے انعامات براؤز کریں، زمرے یا کرنسی کے لحاظ سے فلٹر کریں، اپنی مرضی کے مطابق کلیم کریں، اور انعام وصول کرنے کے لیے اپنا کام جمع کروائیں ۔ ہر صارف شکاری ہو سکتا ہے، کسی درخواست یا گیٹ کیپنگ کی ضرورت نہیں ہے ۔',
    workB3: 'فضل کے زمرے:',
    workB3Desc: 'انعامات کو سوشل میڈیا، کلپنگ اور معاہدوں میں منظم کیا جاتا ہے، لہذا مشغولیت کے کام اور کام کے لمبے ٹکڑے ہر ایک کی اپنی لین ہوتی ہے ۔',
    workB4: 'ایسکرو پروٹیکشن:',
    workB4Desc: 'ہر انعام اس وقت ایسکرو میں رکھا جاتا ہے جب کوئی انعام پوسٹ کیا جاتا ہے، اور دونوں اطراف کی حفاظت کرتے ہوئے، کام قبول ہونے کے بعد ہی شکاری کو جاری کیا جاتا ہے ۔',
    workB5: 'مشغولیت اور ترقی:',
    workB5Desc: 'تخلیق کار اپنی کمیونٹیز کو بڑھانے کے لیے انعامات پوسٹ کرتے ہیں، اور ڈی ہب کمیونٹی ایکو سسٹم کو خود کو فروغ دینے اور وسعت دینے کے لیے انعامات پوسٹ کرتی ہے، جس سے پروموشن کو انعام یافتہ، ٹریک کرنے کے قابل سرگرمی میں تبدیل کیا جاتا ہے ۔',
    workB6: 'تنازعات:',
    workB6Desc: 'ایک سرشار تنازعہ کا بہاؤ ڈیلیوری پر اختلافات کو حل کرتا ہے، لہذا ایسکروڈ انعامات ہمیشہ منصفانہ طور پر طے کیے جاتے ہیں ۔',
    storesTitle: 'اسٹورز',
    storesDesc: 'اسٹورز تخلیق کاروں اور کاروباری اداروں کو DeHub کے اندر ایک مقامی اسٹور فرنٹ کھولنے دیتے ہیں اور براہ راست اپنے سامعین کو فروخت کرتے ہیں، DeHub ٹوکنز میں آباد ہوتے ہیں ۔ ایک اسٹور اپنے صفحے پر رہتا ہے، تخلیق کار کے مواد کے ساتھ بیٹھتا ہے، اور پیروکاروں کو بیرونی چیک آؤٹ پر ری ڈائریکٹ کیے بغیر صارفین میں تبدیل کرتا ہے ۔ چونکہ ادائیگی باقی ایپ کی طرح ایک ہی بلٹ ان والٹ سے ہوتی ہے، خریدار ایک دو ٹیپس میں خریداری کر سکتے ہیں اور بیچنے والے براہ راست اپنے بیلنس میں ٹوکن وصول کرتے ہیں ۔',
    storesB1: 'ایک اسٹور کھولیں:',
