    aiSuiteDesc: 'DeHub تخلیق کاروں کے لیے AI ٹولز کا ایک مکمل سیٹ بنڈل بناتا ہے، یہ سب ایپ کے اندر دستیاب ہیں جن میں کوئی بیرونی اکاؤنٹس یا API کیز نہیں ہیں ۔ یہ سوٹ ایک بات چیت کرنے والے اسسٹنٹ، خود مختار ایجنٹس اور ایک نو کوڈ ایپ بلڈر پر محیط ہے، لہذا آپ پلیٹ فارم چھوڑنے کے بغیر آئیڈیا سے جنریٹ شدہ مواد یا ورکنگ منی ایپ پر جا سکتے ہیں ۔',
