    themesTitle: 'موضوعات اور ظاہری شکل',
    themesDesc: 'ڈی ہب گیارہ ظہور کے اختیارات بھیجتا ہے، نہ کہ ہلکا اور گہرا ٹوگل: سسٹم، لائٹ، کم سے کم، برہمانڈیی، ہیزی، سوارمز، لاوا لیمپ، ونٹر، وار، اوساکا اور جنگل ۔ ہر ایک مکمل جلد ہے — اس کی اپنی پیلیٹ، کروم، آئکنگرافی اور، ان میں سے کئی کے لئے، GPU پر پیش کردہ ایک زندہ متحرک پس منظر ۔ ترتیبات کی → ظاہری شکل میں سے ایک کا انتخاب کریں ؛ ان میں سے چار آپ کو اپنا لہجہ کا رنگ بھی سیٹ کرنے دیتے ہیں ۔ جزیرہ، ہیکر اور ہارر ان کے پیچھے قطار میں لگے ہوئے ہیں ۔',
