    ourService: 'ہماری سروس',
    ourServiceText1: 'سروس آپ کو مکمل طور پر وکندریقرت ماحول میں مواد کو دریافت کرنے، شیئر کرنے اور رقم کمانے کی اجازت دیتی ہے، لوگوں کو دنیا بھر میں دوسروں کو مربوط کرنے، مطلع کرنے اور متاثر کرنے کے لئے ایک فورم فراہم کرتی ہے، اور مرکزی پابندیوں کے بغیر اصل مواد تخلیق کاروں کے لئے تقسیم کے پلیٹ فارم کے طور پر کام کرتی ہے ۔ ہم ایک سنسرشپ مزاحم پلیٹ فارم فراہم کرتے ہیں جہاں کوئی بھی کارپوریٹ کنٹرول کے بجائے کمیونٹی گورننس کے ذریعے اپنے مواد سے رقم کما سکتا ہے ۔',
    ourServiceText2: 'ڈی ہب ایک وکندریقرت پروٹوکول کے طور پر کام کرتا ہے جہاں مواد کی اعتدال پسندی کو کمیونٹی گورننس کے ذریعہ سنبھالا جاتا ہے، اس بات کو یقینی بناتا ہے کہ صرف غیر قانونی مواد یا کمیونٹی سے منظور شدہ رہنما خطوط کی خلاف ورزی کرنے والے مواد کو محدود کیا جاسکتا ہے ۔',
    softwareDevelopers: 'DeHub کون چلاتا ہے',
    softwareDevText1: 'ڈی ہب ایک آزاد ڈی اے او ہے ۔ کوئی بھی کمپنی سروس کی ملکیت، آپریٹنگ یا کنٹرول نہیں کرتی ہے ۔ پروٹوکول، پلیٹ فارم اور ٹریژری ڈی ہب گورننس پروٹوکول کے ذریعے ڈی ہب ٹوکن ہولڈرز کے ذریعہ آن چین کنٹرول کیے جاتے ہیں، جو براہ راست ہے: تجاویز اٹھائی جاتی ہیں اور ایپ میں ووٹ ڈالے جاتے ہیں، اور اس کا نتیجہ ماحولیاتی نظام کو پابند کرتا ہے ۔ اس معاہدے میں "ڈی ہب"، "ہم"، "ہم" اور "ہمارے" کا مطلب ڈی اے او اور اس کے زیر انتظام پروٹوکول ہے، کمپنی نہیں ۔',
    softwareDevText2: 'ترقی ڈی اے او کی طرف سے مصروف آزاد شراکت داروں اور اسٹوڈیوز کی طرف سے کیا جاتا ہے. ان میں سے کوئی بھی ڈی ہب ماحولیاتی نظام کا مالک نہیں ہے یا اس پر فیصلہ سازی کا اختیار نہیں رکھتا ہے، اور ان میں سے کسی کو گورننس ووٹ کے ذریعہ تبدیل یا ہٹایا جاسکتا ہے ۔ اس عمل سے باہر کوئی بھی پروٹوکول، ٹوکن یا ان شرائط کو تبدیل نہیں کر سکتا ۔',
    whoMayUse: 'سروس کون استعمال کر سکتا ہے ؟',
