    q23: 'کیا پوسٹنگ مفت ہے ؟',
    a23: 'ہاں، روزانہ کے الاؤنس تک جو آپ کے اسٹیکنگ بیج کے ساتھ ترازو کرتا ہے ۔ ہر اکاؤنٹ کو روزانہ دس ٹیکسٹ پوسٹس اور ایک گیگا بائٹ ویڈیو، تصاویر اور آڈیو مفت ملتی ہیں، اور دونوں پولز آدھی رات UTC پر ری سیٹ ہوتے ہیں ۔ ماضی میں، اس دن کے باقی حصوں کی قیمت ڈی ہب ٹوکنز میں ہوتی ہے — تقریبا 10c ایک ٹیکسٹ پوسٹ اور $ 2 ایک گیگا بائٹ، جو پرو رٹا چارج کیا جاتا ہے اور صرف اس حصے پر جو ختم ہوتا ہے ۔ دوبارہ پوسٹ، تبصرے، رد عمل، تجاویز اور پیغامات کبھی بھی اس کے خلاف شمار نہیں ہوتے ہیں ۔',
    q24: 'کیا مجھے اپنی پوسٹس کو این ایف ٹی کے طور پر ڈھکنا ہے ؟',
    a24: 'نہیں ۔ ٹکسال لگانا اختیاری ہے ۔ ایک پوسٹ آپ کے بھیجتے ہی آف چین شائع کرتی ہے، جس میں کوئی بٹوے کا دستخط اور کوئی گیس نہیں ہوتی ہے، اور اگر آپ ERC -1155 اور اس کے ساتھ آنے والی رائلٹی چاہتے ہیں تو آپ اسے بعد میں پوسٹ سے ہی ٹکسال کر سکتے ہیں ۔',
    q25: 'اسٹیکنگ بیج دراصل مجھے کیا ملتا ہے ؟',
    a25: 'ایک بیج آپ کے پلیٹ فارم کی فیس کو 0.69% فی درجہ کم کرتا ہے، آپ کے مفت یومیہ پوسٹنگ الاؤنس میں اضافہ کرتا ہے اور اس سے آگے کسی بھی چیز پر چھوٹ دیتا ہے، DeHub ٹوکن خریدتے وقت آپ کو وہی 5% -30% کی رعایت دیتا ہے، سپر پاورز اور پروفائل کاسمیٹکس کو ان لاک کرتا ہے، اور آپ کے خیالات اور رد عمل کو مزید شمار کرتا ہے ۔ تیرہ درجوں کی قیمت ایک مقررہ تعداد میں ٹوکنز کے بجائے ڈالر میں ہوتی ہے، اور ایک بار جب آپ نے ایک درجہ حاصل کر لیا تو قیمت اسے آپ سے واپس نہیں لے سکتی ۔',
    q26: 'کیا میں اپنا بیج کسی اور کو ادھار دے سکتا ہوں ؟',
    a26: 'جی ہاں ۔ آپ جو بھی رنگ پر چڑھتے ہیں وہ آپ کو ایک وفد کا سلاٹ دیتا ہے، اور ایک سلاٹ دوسرے اکاؤنٹ کو آپ کے اپنے درجے کا قرض دیتا ہے جب تک کہ آپ اسے وہاں چھوڑ دیتے ہیں — لہذا ایک عملہ یا دوسرا اکاؤنٹ اس درجے کا حامل ہوتا ہے جو اس کی حمایت کرتا ہے ۔ ایک تفویض کردہ بیج اپنے سبسکرائبر کا نام ہوور پر رکھتا ہے، اور اسے کسی بھی وقت واپس لے جایا جا سکتا ہے ۔ اس میں درجے کا وزن ہوتا ہے لیکن وہ چیزیں نہیں جن کی قیمت پیسوں میں ہوتی ہے: آپ کی فیس کا درجہ، خریداری کی رعایت، پوسٹنگ الاؤنس اور وفد کے سلاٹس سب اب بھی اس داؤ سے آتے ہیں جو آپ خود رکھتے ہیں ۔',
    q27: 'مراحل کیا ہیں ؟',
    a27: 'DeHub میں بنائے گئے لائیو آڈیو رومز ۔ ایک میزبان ایک کمرہ کھولتا ہے اور مقررین کو اسٹیج پر لاتا ہے، سامعین اسٹیج کے صفحے یا مشترکہ لنک سے آتے ہیں، اور پروڈکشن لیئر ایک DJ ساؤنڈ بورڈ، صوتی اثرات، ریڈیو اسٹیشن، اسکرین شیئر اور براؤزر گو لائیو شامل کرتی ہے جس میں OBS کی ضرورت نہیں ہوتی ہے ۔ کمروں میں لائیو سب ٹائٹلز ہوتے ہیں جن کا ترجمہ ہر سننے والا جو بھی زبان میں پڑھتا ہے، میزبان کی اپنی کلون کی آواز میں بلند آواز سے ڈب کیا جا سکتا ہے، اور اس کے بعد قابل تلاش ری پلے کے لیے ہر اسٹیج ریکارڈ کیا جا سکتا ہے ۔',
    q28: 'کیا میں اپنے فون پر DeHub استعمال کر سکتا ہوں ؟',
    a28: 'جی ہاں ۔ اینڈرائیڈ ایپ گوگل پلے پر ہے، اور تازہ ترین تعمیر dehub.io/apk سے براہ راست APK ڈاؤن لوڈ بھی ہے ۔ dehub.io پر ویب ایپ کسی بھی ڈیوائس پر آپ کی ہوم اسکرین پر انسٹال ہوتی ہے ۔ آپ کا اکاؤنٹ، بیج اور بیلنس ان سب پر یکساں ہیں ۔',
    q29: 'میں جو دیکھتا ہوں اسے کیسے کنٹرول کروں ؟',
    a29: 'تخلیق کار اسے تحریر کرتے وقت ایک پختہ پوسٹ کو نشان زد کرتے ہیں، اور وہ پوسٹس عوامی ہوم فیڈ سے دور رہتی ہیں اور تلاش سے باہر رہتی ہیں جب تک کہ آپ ترتیبات میں "پختہ مواد دکھائیں" کو آن نہیں کرتے ہیں ۔ آپ کسی مصنف کو کسی بھی پوسٹ سے براہ راست خاموش کر سکتے ہیں، ان کے پروفائل سے بلاک کر سکتے ہیں، اور فی زمرہ منتخب کر سکتے ہیں جس کی اطلاعات آپ تک بالکل بھی پہنچتی ہیں ۔',
    q30: 'DeHub کس زبان میں ہے ؟',
    a30: 'سو سے زیادہ ۔ پوسٹس اور تبصرے آپ کی زبان میں ترجمہ کرتے ہیں جب آپ اسکرول کرتے ہیں جس میں سیٹ اپ کرنے کے لئے کچھ نہیں ہوتا ہے اور کسی بٹوے کے کنکشن کی ضرورت نہیں ہوتی ہے، انٹرفیس کا خود ترجمہ کیا جاتا ہے، اور براہ راست مراحل کو حقیقی وقت میں کیپشن اور ترجمہ کیا جاتا ہے ۔',
